import { Button, Card, CardContent, Typography } from "@mui/material";
import { FC } from "react";
import HomeWorkIcon from "@mui/icons-material/HomeWork";
import LocalPhoneIcon from "@mui/icons-material/LocalPhone";
import { Address } from "../../models/Address";

interface AddressTypeComponentProps {
  addressItem: Address;
}

export const AddressTypeComponent: FC<AddressTypeComponentProps> = ({
  addressItem
}) => {
  return (
    <>
      <Card
        sx={{
          width: "100%",
          padding: "1%",
          paddingTop: "0px",
          paddingBottom: "0px"
        }}
      >
        <CardContent>
          <Typography
            sx={{ fontSize: 14 }}
            color="text.secondary"
            gutterBottom
            style={{ fontWeight: "bold" }}
          >
            <HomeWorkIcon></HomeWorkIcon> {addressItem.title}
          </Typography>

          <Typography variant="body2">{addressItem.address}</Typography>
        </CardContent>
        {addressItem.phone && (
          <a href="tel:PHONE">
            <Button
              style={{
                marginLeft: "10px",
                marginBottom: "2px",
                fontWeight: "bold",
                color: "#000"
              }}
            >
              <LocalPhoneIcon color="primary" /> {addressItem.phone}
            </Button>
          </a>
        )}
      </Card>
      <br />
    </>
  );
};
